@@ -1,61 +0,0 @@
-//! Three replicas and a client in one thread. The loop delivers whatever
-//! the replicas and the client want sent, until nothing is left.
-
-use vsr_rs::{Client, Config, Message, Replica, ReplicaID, StateMachine};
-
-fn main() {
-    env_logger::init();
-    let mut config = Config::new();
-    for _ in 0..3 {
-        config.add_replica();
-    }
-    let mut replicas: Vec<Replica<Accumulator>> = (0..3)
-        .map(|id| Replica::new(id, config.clone(), Accumulator::default()))
-        .collect();
-    let mut client = Client::new(0, config);
-    let tick = |replicas: &mut Vec<Replica<Accumulator>>, client: &mut Client<Op>| loop {
-        let mut queue: Vec<(ReplicaID, Message<Op>)> = client.drain().collect();
-        for replica in replicas.iter_mut() {
-            queue.extend(replica.drain_messages());
-            for reply in replica.drain_replies() {
-                println!("Reply {reply:?}");
-            }
-        }
-        if queue.is_empty() {
-            break;
-        }
-        for (replica_id, message) in queue {
-            println!("Sending {message:?} to {replica_id}");
-            replicas[replica_id].on_message(message);
-        }
-    };
-    for op in [Op::Add(10), Op::Sub(5), Op::Add(7), Op::Add(8)] {
-        client.on_request(op);
-        tick(&mut replicas, &mut client);
-    }
-}
-
-#[derive(Clone, Debug)]
-enum Op {
-    Add(i32),
-    Sub(i32),
-}
-
-#[derive(Default)]
-struct Accumulator {
-    value: i32,
-}
-
-impl StateMachine for Accumulator {
-    type Input = Op;
-    type Output = i32;
-
-    fn apply(&mut self, op: Op) -> i32 {
-        match op {
-            Op::Add(value) => self.value += value,
-            Op::Sub(value) => self.value -= value,
-        }
-        println!("Applied {op:?}, value is now {}", self.value);
-        self.value
-    }
-}
